set -euo pipefail
test "$(hostname)" = racknerd-f0269d5
exec 8>/opt/quiz-master/DEPLOY.lock
flock -n 8
python3 - <<'PY'
import base64,json,hashlib,subprocess,pathlib,stat,sqlite3,os,urllib.request
def status():
 h=json.loads(subprocess.check_output(['helm','status','quiz-master','-n','quiz-master','-o','json']))
 x=json.loads(subprocess.check_output(['kubectl','get','deploy','quiz-master','-n','quiz-master','-o','json']))
 p=json.loads(subprocess.check_output(['kubectl','get','pvc','quiz-data','-n','quiz-master','-o','json']))
 assert h['version']==59 and h['info']['status']=='deployed'
 assert x['status'].get('availableReplicas')==1 and p['metadata']['uid']=='7fc2428f-4146-4c78-a26d-2347d9f3b7bf'
 assert len(x['spec']['template']['spec']['containers'])==2 and all(c['image']=='docker.io/library/quiz-master@sha256:95ad1112d272b6cec48d517b350285ed560687cec4a8fc8f7d1b99e6d27cf2af' for c in x['spec']['template']['spec']['containers'])
 node=json.loads(subprocess.check_output(['kubectl','get','nodes','-o','json']))['items'][0]
 conditions={c['type']:c['status'] for c in node['status']['conditions']};assert conditions['Ready']=='True' and conditions['DiskPressure']=='False'
 with urllib.request.urlopen('https://quiz.kotopedia.org/health/ready',timeout=15) as r:assert r.status==200
 db=sqlite3.connect('file:/var/lib/rancher/k3s/storage/pvc-7fc2428f-4146-4c78-a26d-2347d9f3b7bf_quiz-master_quiz-data/quiz.db?mode=ro',uri=True)
 rows=db.execute('select * from feedback_reports order by rowid').fetchall();digest=hashlib.sha256(json.dumps(rows,ensure_ascii=False,default=str).encode()).hexdigest();assert len(rows)==29 and digest=='452929a2ea8dc34600eff8039571e2b0479ec7ad1ec52fa6e271b5c71008030e'
 assert db.execute("select count(*) from feedback_reports where status='open'").fetchone()[0]==29
 st=os.statvfs('/var/lib/rancher/k3s')
 return {'helm_revision':59,'feedback_count':29,'all_feedback_open':True,'feedback_sha256':digest,'available':st.f_bavail*st.f_frsize,'total':st.f_blocks*st.f_frsize,'release20percent_pass':st.f_bavail*5>=st.f_blocks}
protected=[pathlib.Path('/opt/quiz-master/backups')/name for name in ['quiz-2026.10.14-library-09b19cc-publish-20261014T223958Z.sqlite','quiz-2026.10.15-reader-06dfa0b-publish-20261015T034437Z.sqlite']]
def protected_hashes():
 out={}
 for p in protected:
  assert p.is_file() and not p.is_symlink() and stat.S_IMODE(p.stat().st_mode)==0o600
  with sqlite3.connect(p.as_uri()+'?mode=ro&immutable=1',uri=True) as db:assert db.execute('pragma integrity_check').fetchone()==('ok',)
  out[p.name]=hashlib.sha256(p.read_bytes()).hexdigest()
 return out
before=status();saved=protected_hashes()
source=base64.b64decode('')
plan_bytes=base64.b64decode('')
assert hashlib.sha256(source).hexdigest()=='2640bb0c0a5ed72dae96aeee56ca7e3df1831569c10a0649602f56fc2ed6fdb5'
assert hashlib.sha256(plan_bytes).hexdigest()=='59959e210ac267d98fdd31bc7774c4bba5bfb3f323e901a921b556e3d1b02dcc'
plan=json.loads(plan_bytes);assert len(plan['groups'])==5 and plan['expected_files']==24 and sum(len(g['duplicates']) for g in plan['groups'])==19
env={'__name__':'qm_cold_backup_dedup'};exec(compile(source,'deduplicate.py','exec'),env)
receipt=env['run'](plan)
assert receipt['logical_bytes_removed']==887103488 and receipt['unique_states_retained']==5
assert protected_hashes()==saved
after=status()
print(json.dumps({'status':'COLD_DUPLICATES_REMOVED_UNIQUE_STATES_RETAINED','before':before,'after':after,'protected_backup_sha256':saved,'receipt':receipt}))
PY
